<?php
 namespace Pterodactyl\Services\Dezerx; use Illuminate\Http\UploadedFile; use Illuminate\Support\Facades\Storage; use Illuminate\Support\Str; use Pterodactyl\Models\User; class Avatars { public const MAX_KILOBYTES = 3072; public const MAX_SIDE = 4000; public const MIMES = 'jpeg,jpg,png,gif,webp'; public const SIZE = 256; private const DISK = 'local'; private const FOLDER = 'avatars'; private const MAX_PIXELS = 12000000; private const QUALITY = 82; private const KINDS = [IMAGETYPE_JPEG, IMAGETYPE_PNG, IMAGETYPE_GIF, IMAGETYPE_WEBP]; public static function hash(?User $user): string { return $user === null ? '' : md5(Str::lower($user->email)); } public static function custom(?User $user): ?string { $stamp = self::stamp($user); return $stamp === null || $user === null ? null : '/api/client/dezerx/avatars/' . $user->uuid . '?v=' . $stamp; } public static function stored(?User $user): ?string { if ($user === null || self::stamp($user) === null) { return null; } $disk = Storage::disk(self::DISK); $file = self::FOLDER . '/' . $user->uuid . '.webp'; return $disk->exists($file) ? $disk->path($file) : null; } public static function store(User $user, UploadedFile $file): bool { $image = self::square($file->getRealPath()); if ($image === null) { return false; } Storage::disk(self::DISK)->put(self::FOLDER . '/' . $user->uuid . '.webp', $image); self::remember($user, time()); return true; } public static function forget(User $user): void { Storage::disk(self::DISK)->delete(self::FOLDER . '/' . $user->uuid . '.webp'); self::remember($user, null); } private static function stamp(?User $user): ?int { $preferences = $user?->dezerx_preferences; $stored = is_array($preferences) ? ($preferences['avatar'] ?? null) : null; $at = is_array($stored) ? ($stored['at'] ?? null) : null; return is_int($at) && $at > 0 ? $at : null; } private static function remember(User $user, ?int $at): void { $preferences = $user->dezerx_preferences ?? []; if ($at === null) { unset($preferences['avatar']); } else { $preferences['avatar'] = ['at' => $at]; } $user->forceFill(['dezerx_preferences' => $preferences])->saveOrFail(); } private static function square(string $path): ?string { $info = @getimagesize($path); if ($info === false || !in_array($info[2], self::KINDS, true)) { return null; } [$width, $height] = $info; if ($width < 1 || $height < 1 || $width > self::MAX_SIDE || $height > self::MAX_SIDE) { return null; } if ($width * $height > self::MAX_PIXELS) { return null; } $source = @imagecreatefromstring((string) @file_get_contents($path)); if ($source === false) { return null; } $side = min($width, $height); $canvas = imagecreatetruecolor(self::SIZE, self::SIZE); imagealphablending($canvas, false); imagesavealpha($canvas, true); imagefill($canvas, 0, 0, imagecolorallocatealpha($canvas, 0, 0, 0, 127)); imagecopyresampled( $canvas, $source, 0, 0, intdiv($width - $side, 2), intdiv($height - $side, 2), self::SIZE, self::SIZE, $side, $side, ); ob_start(); imagewebp($canvas, null, self::QUALITY); $image = (string) ob_get_clean(); imagedestroy($canvas); imagedestroy($source); return $image === '' ? null : $image; } } 